    "theory": 3,
    "practice": 0,
    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Prof. Dr. FİLİZ ÖZBAŞ GERÇEKER",
    "purpose": "İmmunogenetik alanındaki ileri kavramları, araştırma yaklaşımlarını ve biyolojik bulguları lisansüstü düzeyde analiz etme ve değerlendirme yetkinliği kazandırmak.",
    "content": "İmmunogenetik; moleküler temel ve terminoloji, genom organizasyonu, gen ifadesi ve düzenlenmesi, moleküler yöntem seçimi, deneysel tasarım, biyolojik veri kalite kontrolü, istatistiksel ve hesaplamalı analiz, sonuçların biyolojik yorumlanması boyutlarıyla ele alınır.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, biyolojik veri yorumlama, yöntem karşılaştırması ve akademik tartışma.",
    "resources": "Campbell Biology; Alberts ve diğerleri, Molecular Biology of the Cell; konuya ilişkin güncel hakemli biyoloji literatürü ve yetkili bilimsel kurum kaynakları.",
    "sdgs": [
      "3",
      "4",
      "9"
    ],
    "outcomes": [
      "İmmunogenetik kapsamındaki ileri biyolojik kavramları analiz eder.",
      "moleküler biyoloji, genetik ve biyolojik veri analizi alanındaki bilimsel yaklaşımları karşılaştırır.",
      "İmmunogenetik için uygun araştırma veya inceleme yöntemini uygular.",
      "İmmunogenetik verilerini bilimsel ölçütlerle değerlendirir.",
      "İmmunogenetik bulgularını etik ve biyolojik bağlamda yorumlar."
    ],
    "weeklyTopics": [
      "İmmunogenetik: kapsam, temel kavramlar ve terminoloji",
      "moleküler temel ve terminoloji: kuramsal çerçeve",
      "genom organizasyonu: mekanizmalar ve ilişkiler",
      "gen ifadesi ve düzenlenmesi: güncel bilimsel yaklaşımlar",
      "moleküler yöntem seçimi: araştırma sorularının kurulması",
      "deneysel tasarım: yöntem ve ölçütlerin seçimi",
      "biyolojik veri kalite kontrolü: veri üretimi ve kalite güvencesi",
      "istatistiksel ve hesaplamalı analiz: çözümleme ilkeleri",
      "İmmunogenetik: örnek araştırmaların karşılaştırılması",
      "sonuçların biyolojik yorumlanması: bulguların yorumlanması",
      "İmmunogenetik: disiplinler arası bağlantılar",
      "İmmunogenetik: etik, güvenlik ve sınırlılıklar",
      "İmmunogenetik: çevresel veya toplumsal etkilerin değerlendirilmesi",
      "İmmunogenetik: güncel literatürün eleştirel incelenmesi",
      "İmmunogenetik: bütünleşik bilimsel değerlendirme"
    ],
