    "content": "Değişik familyalara ait polen yapılarının exin, intin, aperture, ornemantasyonlarının incelenerek mikro metrik ölçümler ve mikroskobik fotoğraflamanın nasıl yapılacağına dair bilgi ve inceleme metotlarının öğretilmesi",
