      "güncel bilimsel gelişmeler: bulguların yorumlanması",
      "Bilimsel araştırma yöntemleri ve yayın etiği: disiplinler arası bağlantılar",
      "Bilimsel araştırma yöntemleri ve yayın etiği: etik, güvenlik ve sınırlılıklar",
      "Bilimsel araştırma yöntemleri ve yayın etiği: çevresel veya toplumsal etkilerin değerlendirilmesi",
