    "content": "Canlıların sınıflandırma prensipleri, omurgasız hayvan şubelerinin genel özellikleri, sınıflandırılmaları, biyolojileri, ekolojileri ve filogenetik ilişkileri.",
    "methods": "Yüz yüze, soru cevap ve power point sunusu.",
    "resources": "Kaynaklar: Yaşamın Temel Kuralları, Omurgasızlar - İnvertebrata (Böcekler Dışında), Demirsoy, A., Meteksan, 2003. Yaşamın Temel Kuralları, Omurgasızlar Invertebrata, Demirsoy, A., Meteksan, 1999.; Ders Notları: Salman, S., Omurgasız Hayvanlar Biyolojisi, Palme Yayınları, 2007",
