      "EIS",
      "Mikrobiyal korozyonun belirlenmesinde biyolojik yöntemler-1",
      "Mikrobiyal korozyonun önlenmesi-1",
      "Mikrobiyal korozyonun önlenmesi-2",
      "İnhibitör maddeler",
      "İnhibitör maddeler ve kullanımları",
      "Mikrobiyal korozyon: kapsam, temel kavramlar ve terminoloji",
      "mikrobiyal yapı ve çeşitlilik: kuramsal çerçeve",
      "gelişme ve metabolizma: mekanizmalar ve ilişkiler",
      "konak-mikroorganizma etkileşimi: güncel bilimsel yaklaşımlar"
