      "toksisite ve güvenlik: bulguların yorumlanması",
      "Mantar ekolojisi: disiplinler arası bağlantılar",
      "Mantar ekolojisi: etik, güvenlik ve sınırlılıklar",
      "Mantar ekolojisi: çevresel veya toplumsal etkilerin değerlendirilmesi",
      "Mantar ekolojisi: güncel literatürün eleştirel incelenmesi",
      "Mantar ekolojisi: bütünleşik bilimsel değerlendirme"
